{
    PyObject *ret = NULL;

    static char *kwlist[] = { "windows", "sample_set_sizes", "sample_sets", "indexes",
        "node_bin_map", "span_normalise", "pair_normalise", NULL };
    PyObject *py_sample_set_sizes = Py_None;
    PyObject *py_sample_sets = Py_None;
