from workflow.build_source import load_local_tskit
import numpy as np
tskit = load_local_tskit()
a, b = [tskit.load(f'fixtures/cohort_export_{s}.trees') for s in 'ab']
def retained_edges(ts):
    gaps = [t.interval for t in ts.trees() if t.num_edges == 0]
    def compress(x):
        return x - sum(max(0, min(x, right) - left) for left, right in gaps)
    intervals = {}
    for edge in ts.edges():
        intervals.setdefault((edge.parent, edge.child), []).append((compress(edge.left), compress(edge.right)))
    output = []
    for (parent, child), spans in sorted(intervals.items()):
        merged = []
        for left, right in sorted(spans):
            if merged and merged[-1][1] == left:
                merged[-1] = (merged[-1][0], right)
            else:
                merged.append((left, right))
        output.extend((parent, child, left, right) for left, right in merged)
    return output
print('Identical retained parent-child intervals:', retained_edges(a) == retained_edges(b))
print('Raw coalescence count maximum difference:', np.max(np.abs(a.pair_coalescence_counts(span_normalise=False) - b.pair_coalescence_counts(span_normalise=False))))
print('Normalised coalescence count maximum difference:', np.max(np.abs(a.pair_coalescence_counts() - b.pair_coalescence_counts())))
